head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 패널 라운드 처리
    $c.cm.PanelToGroupBox(panel_Top);

    // 라디오 기본값 : 사업목적
    rdo_Fg.setValue("01");

    // rdo_Fg 값에따른 화면 처리
    scwin.rdoFgOnSelChange();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rdo_Fg_OnSelChange
 * @description rdo_Fg 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.rdo_Fg_OnSelChange = function() {
    try {
        // 라디오 클릭
        scwin.rdoFgOnSelChange();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00201.rdo_Fg_OnSelChange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        // 조회버튼 클릭
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00201.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_CoSearch_onclick
 * @description img_CoSearch 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_CoSearch_onclick = async function() {
    try {
        // 기업검색팝업 오픈
        await scwin.comSrchOpen();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00201.img_CoSearch_onclick" });
    }
};

/**
 * @method
 * @name txb_CoSnm_onkeydown
 * @description txb_CoSnm 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_CoSnm_onkeydown = async function() {
    try {
        // 기업명 키다운.
        if (event.keyCode === 13) {
            // 이게 왜 필요하냐구??? kisCD 세팅 후 마우스 포커스가 기업명에서 나갈때 onChange이벤트가 발생해서 kisCd를 지워버리기 때문이다
            $c.frame.focus();
            if (txb_CoSnm.getValue() === "") {
                // 기업검색팝업 오픈
                await scwin.comSrchOpen();
            } else {
                // 기업정보 조회
                await scwin.comInfoSrch();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00201.txb_CoSnm_onkeydown" });
    }
};

/**
 * @method
 * @name txb_CoSnm_onchange
 * @description txb_CoSnm 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_CoSnm_onchange = function() {
    try {
        // 조회조건이 변경된 경우 초기화.
        txb_KisCd.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00201.txb_CoSnm_onchange" });
    }
};

/**
 * @method
 * @name dts_ComInfo_OnLoadCompleted
 * @description dts_ComInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ComInfo_OnLoadCompleted = async function(rowcount) {
    try {
        // 조회결과가 1개이면 기업개황 조회 아니면 기업팝업 오픈.
        if (rowcount === 1) {
            // 조회조건에 값을 세팅하고..
            txb_KisCd.setValue(dts_ComInfo.getCellData(0, "KIS_CD"));

            // 결산일자 visible = true인 경우
            if (pnl_AcntclsDt.style.display === "none" || pnl_AcntclsDt1.style.display === "none") {
                // 기업현황 조회
                await scwin.search();
            } else {
                // 결산일자 조회.
                if (pnl_AcntclsDt.style.display !== "none") {
                    await scwin.srchAcntclsDt();
                }
            }
        } else {
            await scwin.comSrchOpen(); // 기업검색 팝업 오픈

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00201.dts_ComInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_AcntclsDt_OnLoadCompleted
 * @description dts_AcntclsDt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_AcntclsDt_OnLoadCompleted = function(rowcount) {
    try {
        // 결산일자 OnLoadCompleted
        if (rowcount <= 0) {
            alert("결산일자가 존재하지 않습니다.");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00201.dts_AcntclsDt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_AcntclsDt_onselchange
 * @description cmb_AcntclsDt onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_AcntclsDt_onselchange = async function() {
    try {
        // 그리드 헤더에 명을 세팅. 필요한 경우만..
        scwin.getGrdHeaderNm();

        // 기업현황 조회
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00201.cmb_AcntclsDt_onselchange" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        if ($c.frame.path("../frame_body").fn_excel_download) {

            $c.frame.path("../frame_body").fn_excel_download();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00201.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_AcntclsStrtDt_onclick
 * @description img_AcntclsStrtDt 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_AcntclsStrtDt_onclick = function() {
    try {
        popUpCalendar2(edt_AcntclsStrtDt);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00201.img_AcntclsStrtDt_onclick" });
    }
};

/**
 * @method
 * @name img_AcntclsEndDt_onclick
 * @description img_AcntclsEndDt 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_AcntclsEndDt_onclick = function() {
    try {
        popUpCalendar2(edt_AcntclsEndDt);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00201.img_AcntclsEndDt_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_AcntclsStrtDt, edt_AcntclsEndDt);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00201.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name srchAcntclsDt
 * @description 결산일자 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.srchAcntclsDt = async function() {
    // 데이터셋 초기화
    scwin.initDs("2");

    // 결산일자 visible = true인 경우만 조회, KisCd 필수
    if (pnl_AcntclsDt.style.display === "none" || txb_KisCd.getValue() === "") {
        return;
    }
    const sbmOptions = {
        id : "sbm_dts_AcntclsDt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_AcntclsDt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name comInfoSrch
 * @description com Info Srch 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.comInfoSrch = async function() {
    // 데이터셋 초기화
    scwin.initDs("1");

    // 기업명 없으면 중지.
    if (txb_CoSnm.getValue() === "") {
        return;
    }
    const sbmOptions = {
        id : "sbm_dts_ComInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ComInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name rdoFgOnSelChange
 * @description 라디오 OnSelChange
 * @returns {void}
 * @hidden N
 */
scwin.rdoFgOnSelChange = function() {
    const pageNum = rdo_Fg.getValue();
    if (pageNum === "08" || pageNum === "09" || pageNum === "12") {
        img_tmp_11.style.left = 1090 + 81;
        btn_Excel.hide();
    } else {
        img_tmp_11.style.left = 1090;
        btn_Excel.show("");
    }

    // 라디오 클릭 시 하단 프레임에 적당한 화면 세팅.
    scwin.displayFrame(rdo_Fg.getValue());

    // 결산일자 visible
    scwin.displayAcntclsDt();
};

/**
 * @method
 * @name displayFrame
 * @description 하단 frome에 화면 표시
 * @param {*} pVal pVal
 * @returns {void}
 * @hidden N
 */
scwin.displayFrame = function(pVal) {
    $c.frame.path("../frame_body").srcUrl = scwin.getUrl(pVal);
};

/**
 * @method
 * @name getUrl
 * @description url 만들기
 * @param {*} pVal pVal
 * @returns {void}
 * @hidden N
 */
scwin.getUrl = function(pVal) {
    const vUrl = "./ULDFIS00200_" + pVal + ".gfm";
    return vUrl;
};

/**
 * @method
 * @name displayAcntclsDt
 * @description 결산일자 visible
 * @returns {void}
 * @hidden N
 */
scwin.displayAcntclsDt = function() {
    // 주요주주, 배당, 관계회사현황
    if (rdo_Fg.getValue() === "03" || rdo_Fg.getValue() === "06" || rdo_Fg.getValue() === "18") {
        pnl_AcntclsDt1.show("");
        pnl_AcntclsDt.hide();
        //  기간 from~ to  셋팅
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_AcntclsEndDt.setValue(vCurDate); // 현재날짜
        edt_AcntclsStrtDt.setValue($c.ut.cGetMinusDate2(vCurDate, 365));
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    } else if (rdo_Fg.getValue() === "05" || rdo_Fg.getValue() === "07" || rdo_Fg.getValue() === "08" ||
        rdo_Fg.getValue() === "09" || rdo_Fg.getValue() === "11" || rdo_Fg.getValue() === "12" ||
        rdo_Fg.getValue() === "13" || rdo_Fg.getValue() === "14" || rdo_Fg.getValue() === "15" ||
        rdo_Fg.getValue() === "17" || rdo_Fg.getValue() === "19" || rdo_Fg.getValue() === "20") {
        pnl_AcntclsDt.show("");
        pnl_AcntclsDt1.hide();
    } else {
        pnl_AcntclsDt.hide();
        pnl_AcntclsDt1.hide();
    }
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function() {
    // 필수항목 체크.
    if (txb_CoSnm.getValue() === "") {
        alert("기업명을 입력하세요.");
        txb_CoSnm.focus();
        return false;
    }
    if (pnl_AcntclsDt.style.display !== "none" && cmb_AcntclsDt.getValue() === "") {
        alert("결산일자를 입력하세요.");
        cmb_AcntclsDt.focus();
        return false;
    }
    if (pnl_AcntclsDt1.style.display !== "none") {
        if (!$c.stf.compareFromToDate2(edt_AcntclsStrtDt, edt_AcntclsEndDt)) {
            return false;
        }
        if (edt_AcntclsStrtDt.getValue() === "") {
            alert("기간 시작일를 입력하세요.");
            return false;
        }
        if (edt_AcntclsEndDt.getValue() === "") {
            alert("기간 종료일를 입력하세요.");
            return false;
        }
    }

    // 기업명은 있는데 기업코드가 없는 경우
    if (txb_CoSnm.getValue() !== "" && txb_KisCd.getValue() === "") {
        await scwin.comInfoSrch();
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 기업현황 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 조회조건 필수 체크.
    if (!await scwin.chkValid()) {
        return;
    }
    if ($c.frame.path("../frame_body").fn_Search) {
        $c.frame.path("../frame_body").fn_Search();
    }
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @param {*} pFg pFg
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function(pFg) {
    if (pFg === "1") {
        dts_ComInfo.removeAll();
    } else if (pFg === "2") {
        dts_AcntclsDt.removeAll();
    }
};

/**
 * @method
 * @name comSrchOpen
 * @description 기업검색 팝업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.comSrchOpen = async function() {
    const options = {
        id: "ULDFIS00100_P1",
        title: "기업 검색",
        type: "browserPopup",
        width: 640 + 20,
        height: 445 + 45,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("./ULDFIS00100_P1.gfm", options);
};

/**
 * @method
 * @name getParKisCd
 * @description 팝업으로 값을 넘김.
 * @returns {void}
 * @hidden N
 */
scwin.getParKisCd = function() {
    const arrPar = new Array();
    arrPar[0] = txb_CoSnm.getValue(); // 기업명
    return arrPar;
};

/**
 * @method
 * @name setParKisCd
 * @description 팝업에서 넘어온 값 세팅.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParKisCd = async function(arrPar) {
    txb_CoSnm.setValue(arrPar[0].CO_SNM); // 기업명
    txb_KisCd.setValue(arrPar[0].KIS_CD); // 기업코드

    if (txb_KisCd.getValue() !== "") {
        // 결산일자 visible = true인 경우
        if (pnl_AcntclsDt.style.display === "none" && pnl_AcntclsDt1.style.display === "none") {
            // 기업현황 조회
            await scwin.search();
        } else {
            // 결산일자 조회.
            if (pnl_AcntclsDt.style.display !== "none") {
                await scwin.srchAcntclsDt();
            }
        }
    }
};

/**
 * @method
 * @name getKisCd
 * @description 조회조건의 kisCd를 리턴.
 * @returns {void}
 * @hidden N
 */
scwin.getKisCd = function() {
    return txb_KisCd.getValue();
};

/**
 * @method
 * @name getAcntclsDt
 * @description 조회조건의 AcntclsDt를 리턴.
 * @returns {void}
 * @hidden N
 */
scwin.getAcntclsDt = function() {
    return cmb_AcntclsDt.getValue();
};

/**
 * @method
 * @name getAcntclsStrtDt
 * @description 조회조건의 AcntclsStrtDt를 리턴.
 * @returns {void}
 * @hidden N
 */
scwin.getAcntclsStrtDt = function() {
    return edt_AcntclsStrtDt.getValue();
};

/**
 * @method
 * @name getAcntclsEndDt
 * @description 조회조건의 AcntclsEndDt를 리턴.
 * @returns {void}
 * @hidden N
 */
scwin.getAcntclsEndDt = function() {
    return edt_AcntclsEndDt.getValue();
};

/**
 * @method
 * @name getGrdHeaderNm
 * @description 그리드 헤더 명을 구한다.
 * @returns {void}
 * @hidden N
 */
scwin.getGrdHeaderNm = function() {

    if ($c.frame.path("../frame_body").fn_SetGrdHeaderNm) {
        const nCurrRow = dts_AcntclsDt.getRowPosition();
        const nTrgtRow = dts_AcntclsDt.getRowPosition() + 4;
        const aArray = new Array();
        let nArrRow = 0;
        for (let nRow = nCurrRow; nRow <= nTrgtRow; nRow++) {
            aArray[nArrRow] = {
                VALUE: dts_AcntclsDt.getCellData(nRow, "VALUE"),
                TEXT: dts_AcntclsDt.getCellData(nRow, "TEXT")
            };
            nArrRow++;
        }

        // 그리드 헤더 호출

        $c.frame.path("../frame_body").fn_SetGrdHeaderNm(aArray);
    }
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    scwin.init();
};
